// What went live and when, in plain English, newest first. Shown in the Owner area's "Change log" next to the Phases & Tasks change history.
// ADD AN ENTRY (at the top) every time something is put live. The exact technical record is the code history on GitHub; this is the readable version.

export interface ReleaseNote {
  /** when it went live, ISO with the UK offset */
  at: string
  title: string
  detail: string
}

export const RELEASE_NOTES: ReleaseNote[] = [
  { at: '2026-10-18T10:00:00+01:00', title: 'Emailed quotes: a picture pasted into the email is now read', detail: 'A supplier whose system put the quote into the body of the email as a picture (rather than attaching a file) had it thrown away, because every picture the email itself points at was treated as a signature logo, and Emails received said there was no PDF or photo. A picture inside an email that is bigger than about 30 KB is now checked as a possible quote and read like an attached one; small ones (logos, icons) are still ignored. A picture inside the email is only ever checked as a quote: if it is not one it is left alone and not filed in the Documents inbox. The Emails received line now says what came with the email and why it was not used, for example a Word file, a file that was too big, or a logo that was too small to be a quote. No SQL needed.' },
  { at: '2026-10-17T19:00:00+01:00', title: 'Contacts: A to Z strip to jump through a long list', detail: 'A long Contacts list now has a slim A to Z strip down its right-hand side. Press a letter to jump to the first contact starting with it, or press and slide along the strip to run through the list quickly, as in a phone contacts list. It shows only the letters you have, appears once the list has more than 12 contacts, stays in view as you scroll, and follows the type filter (All, Clients, Suppliers, Subcontractors) and the search box. On a phone or tablet the jump leaves room for the bar across the top. No SQL needed.' },
  { at: '2026-10-17T17:00:00+01:00', title: 'Our account number with a supplier, on price requests and orders', detail: 'Editing a supplier or subcontractor in Contacts now has a box, Our account number with them, and the number shows in their details. It is put on what they are sent so they know which account it is for: a line, Our account, in the price request email, in the request WhatsApp and copied message, on the page the supplier opens to give their price, and in the order email and order WhatsApp message. It is looked up when the message is sent, so it always matches Contacts, by the contact the request was made from or, for a supplier typed in by hand, by an exact name when only one supplier has it. A supplier with no account number simply has no line. The WhatsApp and copied message for an amended price request now use the amended wording too (before, only the email did). No SQL needed.' },
  { at: '2026-10-17T14:00:00+01:00', title: 'Suppliers edited in Contacts now show in orders straight away', detail: 'A supplier or subcontractor is kept in two lists in the app, one for Contacts and one for orders, price requests and the Suppliers page, and both were only filled when the app loaded. Editing a supplier in Contacts therefore left the orders dropdown showing the old details until the page was reloaded. The two lists now change together, in both directions: editing, adding or deleting a supplier in Contacts or on the Suppliers page shows in the other at once, and a contact changed so that it is no longer a supplier or subcontractor drops out of the orders dropdown. Orders and requests already made keep the supplier details they were saved with. No SQL needed.' },
  { at: '2026-10-17T10:00:00+01:00', title: 'Price requests: amended requests, and the supplier quote reference', detail: 'When you edit a price request that suppliers already have and really change something (the wording, items, dates, area or how it is priced), it is marked as amended. Each supplier then shows an amber note (their price is for the earlier version, or the request was changed after you sent it) and the button becomes Email the amended request. The amended email and WhatsApp message say the request has changed and ask them to check it and update their price, and quote their earlier reference. Their price page shows an amended box until they reply again, and approving a price given before the change asks you to confirm. Suppliers can also type their own quote reference on their price page, and the app picks up the quote number printed on a quote they email in. It shows on their row (you can type or change it there), goes onto the order made when you approve them, and is quoted back to them in the order email and WhatsApp message. Needs supabase/job-orders-amend.sql run once on each database; until then everything works as before but the amended mark and the references are not kept.' },
  { at: '2026-10-16T21:00:00+01:00', title: 'Price requests and orders: Recently deleted', detail: 'Deleting a price request or an order no longer destroys it. It moves to Recently deleted, a button at the bottom of the Price requests window and of each jobs Orders window, with its suppliers and their replies kept. Restore brings it back exactly as it was, and Delete for good (which asks again) is the only thing that removes it permanently. A deleted request drops out of every list, reminder, the calendar and the expected costs, suppliers who open their link are told it is closed, and an emailed quote is never matched to it. Needs supabase/job-orders-deleted.sql run once on each database; until it has been run, Delete refuses and says so rather than deleting something that cannot be brought back.' },
  { at: '2026-10-16T19:00:00+01:00', title: 'Price request email: tell suppliers they can forward their own quote', detail: 'The email a supplier gets when you ask for a price now has its own box under the Give your price button, Use your own quoting system?, saying they can forward or email their quote (a PDF or a photo) from their own system to your companys quotes address with the PO number on it, and that they do not need to fill in the form as well. Before, this was one small grey line. The same wording is in the message you copy or send by WhatsApp and on the page the supplier opens. The box only shows when your quotes address is set up. No SQL needed.' },
  { at: '2026-10-16T17:00:00+01:00', title: 'Back Office: phases you add yourself are no longer removed', detail: 'A phase added by hand in Back Office, Phases and Tasks (one that is not part of the built-in list) was being deleted, with its sub-phases and tasks, the next time Back Office was opened, because the automatic tidy-up took it for a leftover old phase. That tidy-up now only removes built-in phases the app has retired and never touches a phase the company added itself. A phase already lost this way has to be added again; quotes that used it keep their own copy. No SQL needed.' },
  { at: '2026-10-16T15:00:00+01:00', title: 'Back Office allowances: day rate or hourly rate', detail: 'A sub-phase set to Allowance (the General Preliminaries roles such as Foreman, Projects Manager and Quantity Surveyor) can now be priced three ways, chosen under Priced as: one flat amount as before, a day rate, or an hourly rate. A day or hourly rate takes the rate and a typical number of days or hours, shows the total, and comes into a quote as one line (number times rate) that can be changed for that job. Changing how an allowance is priced clears its amount so an old flat figure is never taken as a rate, and existing flat allowances are unchanged. No SQL needed.' },
  { at: '2026-10-16T12:00:00+01:00', title: 'Quote: rename a phase or room', detail: 'A main phase header in a quote could not be renamed: the app finds a phase by its name, so after the first letter typed the box was rebuilt and lost the cursor. The name box now keeps what you type and applies the new name when you click away or press Enter (Escape puts the old one back). Rooms are fixed the same way. Renaming only changes that one quote, never Back Office or the templates. A blank name is ignored, a name already used in the same quote is refused with a message instead of silently merging two phases, and a renamed phase keeps whether it was open or closed. No SQL needed.' },
  { at: '2026-10-16T09:00:00+01:00', title: 'Phone: bigger small text', detail: 'On a phone (a touch screen up to about 520 pixels wide) the small writing in the main app is a step bigger: notes and hints that were 9 to 11 pixels are now 12 to 13, ordinary text is about a point bigger, and small labels, table headings, status badges and small buttons are lifted too. The cost-type labels in a quote (Labour, Materials and so on) are a little bigger as well. Names, headings and large text are unchanged, and tablets and computers look the same. No SQL needed.' },
  { at: '2026-10-15T22:00:00+01:00', title: 'Emailed quotes: cleaner note', detail: 'When a suppliers emailed quote is read, only what the supplier wrote is kept as their note. The apps own remark that the quote was only read as a total is shown on its own line, and no longer appears in quotation marks as though the supplier had written it. No SQL needed.' },
  { at: '2026-10-15T21:00:00+01:00', title: 'Company email address now uses a hyphen', detail: 'Each companys own quotes and documents address now has its code after a hyphen, for example quotes-ab12cd34@buildospro.ai, instead of a plus sign. Every mail system accepts a hyphen, and the mail host treats it as an ordinary address that its catch-all rule delivers. Addresses with the older plus form are still read. No SQL needed.' },
  { at: '2026-10-15T20:00:00+01:00', title: 'Emails received log, and faster reading of emailed documents', detail: 'Settings, under Your email addresses, now has an Emails received list: the latest emails that reached your quotes or documents address, with what the app did with each (quote added to a request, quote waiting to be placed, filed in the Documents inbox, no attachment, unknown address, or a problem and why). Emailed documents are also read faster: the check for whether it is a supplier quote and the normal document reading now run side by side instead of one after the other, so an emailed invoice does not run into the hosts time limit. Needs the new section at the end of supabase/quote-inbox.sql run once on each database.' },
  { at: '2026-10-15T18:00:00+01:00', title: 'Suppliers can email their own quote', detail: 'A supplier who would rather use their own quoting system can now email their quote, with your PO number on it, to your quotes email address (shown in Settings under Your email addresses, and in every price request email and message). The app reads the PDF or photo, works out which price request and which supplier it is from using the PO number and who sent it, and adds it as their reply, marked Read by the app, so please check it, with a link to view their original. Approve stays switched off until you press Looks right. A quote that has no PO number, or that the app cannot place with confidence, waits in an Emailed quotes to place box under Jobs, Price requests (and on your dashboard) for you to choose the request and supplier. A quote that is not set out item by item like your request is kept as a total. You can also drop a quotes PDF onto a supplier yourself with Add their own quote (PDF). Invoices and receipts emailed to the same address still go to your Documents inbox as before. Every company has its own code in the address (quotes+code@), so many builders can share one quotes address. Needs supabase/quote-inbox.sql run once on each database and the quotes email address set on the host.' },
  { at: '2026-10-15T15:00:00+01:00', title: 'AI quoting fits on a phone', detail: 'The AI scope screen was three columns side by side, so on a phone or a tablet held upright the AI writer was cut off. On a narrow screen it now shows two tabs, Scope of works and AI writer, one at a time at full width (nothing is lost when you switch), with the job setup folded into a box you tap to open, a taller AI writer, and the Generate Scope, Build Estimate and Scope Only buttons wrapping onto a second line. On a wide screen it is still three columns. Also on a phone, the dark phase bars in a quote now wrap so the phase name stays visible next to the price and the Room and Sub-phase buttons, and the long cost-type labels such as Subcontractors fit inside their tiles. No SQL needed.' },
  { at: '2026-10-15T12:00:00+01:00', title: 'Notifications on your phone and tablet', detail: 'Settings now has a Notifications area at the top. Press Turn on notifications on this device on each phone or tablet and allow notifications when asked, and the app alerts you even when it is closed: when a supplier replies to a price request, when a subcontractor sends a site note or a timesheet, and with a short morning summary (only if something needs you) of late deliveries, invoices that have not arrived, overdue invoices and prices waiting to be compared. Tapping an alert opens the right screen. There is a Send me a test button, a switch for each kind of alert and a master switch to pause them all. On an iPhone or iPad the app has to be added to the Home Screen first, and Settings explains how. Alerts go to the company owner. Needs supabase/push-notifications.sql to be run once on each database, and four settings (the notification keys, subject and the daily-summary secret) to be added to the host.' },
  { at: '2026-10-15T10:00:00+01:00', title: 'Price requests: easier to find the replies', detail: 'The email you get when a supplier replies to a request for prices now has a See the prices button that opens the request itself: the jobs Orders window, or the Price requests list when it is not for a job yet, instead of just the Jobs page. The Price requests button is now also in the Jobs header on a phone or tablet; before it was only on the computer. No SQL needed.' },
  { at: '2026-10-14T20:00:00+01:00', title: 'Price requests: linked products asked for in their own unit; saves without the new column', detail: 'When a calculators materials list is sent to suppliers for prices, a line that is linked to a Back Office product is now asked for as that product: its name, in its own unit, and for a product sold in packs or rolls the number of whole packs. A line the calculator counts in square metres that is linked to a product sold per item is now asked for as that many items, not as square metres. Lines with no link are asked for as the calculator has them, and the calculators own print and CSV lists are unchanged. Also, if a database has not yet had supabase/job-orders-lines.sql or job-orders-materials.sql run, an order or price request now still saves, with the list of items written into its details (one price for the whole list), and a message names the file to run, instead of failing with a database error.' },
  { at: '2026-10-14T18:30:00+01:00', title: 'Subcontractor portal: bigger, clearer text', detail: 'The small writing on the subcontractor portal is larger. The Your next days on site card on the dashboard and the My schedule page have bigger day names, job lines, addresses and tags, and the summary card labels are bigger. The whole portal is also scaled up a little: Normal text is about 8 percent larger than before and Large about 25 percent larger (it was 15), so the timesheet and notes pages get a bit bigger too. A subcontractor can still switch between Normal and Large from the paintbrush in the top corner, under Your look. No SQL needed.' },
  { at: '2026-10-14T17:00:00+01:00', title: 'Subcontractor portal: times on a split day', detail: 'When a subcontractor chooses Split day in Add my time, the form now asks for the start and finish time of each half: first job start and finish, and second job start and finish. They are optional, pay is still two half days, and each halfs times go to the office with its timesheet. A half that finishes before it starts is refused, and so are two halves that overlap; halves that meet exactly are fine and either job can be the morning. No SQL needed.' },
  { at: '2026-10-14T15:00:00+01:00', title: 'Calendar: progress on the bars and one-click 100%', detail: 'A task that is part finished now shows it on the Calendar: the finished part of its bar is drawn darker, so a task at 80 percent reads as about four fifths filled (spread correctly over the weeks it runs), and the bar label, Day view card, phone and tablet list and task panel say the percentage. A task at 100 percent looks as before, hatched and marked Complete. In the task panel there is now a green 100% done button that marks the task done and saves straight away with no typing, plus 25, 50 and 75 percent buttons that fill the box, and each unfinished task card in the Day view has a small 100% button. The jobs own Gantt chart is not changed. No SQL needed.' },
  { at: '2026-10-14T13:00:00+01:00', title: 'Price requests: pick the items from your products', detail: 'A request for prices on materials now has an Items to be priced list that you build from your Back Office products, with a quantity for each, or by typing a line in by hand. A product that is not in Back Office can be created from the same product list with New Product, which saves it to Back Office and adds it to the list. A product added twice adds to its quantity. It is there in a jobs Orders window (Ask for a price, then Materials delivery) and on a calculators Prices window, where the calculators materials start as the list and can be changed, with products or lines added. The email, WhatsApp message and order confirmation now build their lists from the items, and the detail box on a materials request is a note for the supplier. No new SQL needed beyond job-orders-lines.sql.' },
  { at: '2026-10-14T11:00:00+01:00', title: 'Price requests: a price for each item', detail: 'A request for prices made from a calculators materials list now lets the supplier price every item separately. Their page shows a card for each item with its quantity, a unit price box with the line total worked out, a tick for cannot supply and a note or alternative, then a delivery charge and a running total saying how many items are priced. You see each suppliers total with how many items they priced, and a Compare line by line table with items down the side and suppliers across, the cheapest for each item shaded green, delivery and total underneath, plus what buying each item from whoever is cheapest would come to for information. An answer that leaves items out is never flagged as the cheapest, because it would always look cheaper. Approving still takes one suppliers whole answer. Needs supabase/job-orders-lines.sql to be run once on each database; requests made before still work with one total price.' },
  { at: '2026-10-14T09:00:00+01:00', title: 'Invoices: stage payments now go to Xero at their percentage', detail: 'An invoice line set to a percentage of its price (a stage payment such as 40 percent of Foundations) was totalled correctly in the app but sent to Xero, and shown on the printed and emailed invoice, at the full price. It is now sent and shown as the part: the description says for example Foundations (40% of 10,000.00) and the amount is the 40 percent. Lines at 100 percent and ordinary lines are unchanged. An invoice already sent to Xero with the wrong amounts can be pushed again to correct it. No SQL needed.' },
  { at: '2026-10-13T22:00:00+01:00', title: 'Calculators: ask suppliers for prices on a materials list', detail: 'Every calculator with a materials list now has a Prices button next to Print and CSV. It asks one or more suppliers or merchants to price the whole list: each gets their own link by email or WhatsApp and gives one price for everything, with their delivery date and how long the price stands, no login. They see what to buy and how much, with waste allowed for, never your own prices, and only the area of the job. It works before there is a job, while you are pricing a quote: those requests are kept under Jobs, Price requests, and you attach one to a job when it is won, then approve a price like any other request. A typed area such as Tooting, SW17 is now shown to suppliers whole. Needs supabase/job-orders-materials.sql to be run once on each database.' },
  { at: '2026-10-13T21:00:00+01:00', title: 'Calendar: deliveries and collections from Orders', detail: 'The Calendar now shows each orders delivery day, and the collection day of skips, portaloos and plant, as small chips on their day in the month, week and day views and in the phone and tablet list. A dashed chip is an order not yet sent to the supplier, a struck-through faded chip has arrived or been collected. Click a chip to see the date and time slot, status, job, full site address, site contact, access notes and expected cost, mark it arrived or collected straight from the calendar, or open that jobs Orders. Dates are changed in the jobs Orders, and the chips are hidden while the calendar is filtered to one person. No SQL needed.' },
  { at: '2026-10-13T20:00:00+01:00', title: 'Dashboard: margins count expected costs, and order reminders', detail: 'The Job margins card on the dashboard now includes orders on account that have no invoice yet, so a job with a skip or hire on order shows its lower margin straight away, with a note of how much is expected. Needs your attention now also lists orders: a price you approved but have not sent the order for, suppliers who have replied to a price request, a cost that looks like the invoice for an order (so the margin is not counting both), a delivery date that has passed with no word that it arrived, a supplier invoice that was expected by now, and hire still on site longer than planned. Click one to open that jobs Orders window. The on-site-too-long warning now only shows once an order is marked delivered.' },
  { at: '2026-10-12T22:00:00+01:00', title: 'Job orders: ask suppliers for a price with a no-login form', detail: 'In a jobs Orders window, Ask for a price lets you ask one or more suppliers to quote for a skip, hire or materials. Each supplier gets their own secret link by branded email or WhatsApp and opens a simple page, no login, showing what is wanted, when and only the area of the job, never the street. They give a price excluding VAT (one price, per day or per week), their earliest delivery date, how long the price stands and any notes, or say they cannot do it, and can change their answer until you decide. You are emailed when a reply arrives. The replies sit side by side with the cheapest flagged and hire worked out for the planned time. Approve this price turns the request into an order with the same PO number at their price and date, counts it as an expected cost straight away (or a paid cost for materials paid at once), marks the other suppliers as not chosen, and Send confirmation then sends the supplier the full order with the full address and the PO to quote on the invoice. Needs supabase/job-orders-quotes.sql to be run once on each database.' },
  { at: '2026-10-12T20:30:00+01:00', title: 'Job orders: skips, hire and materials with a PO number and expected costs', detail: 'Every job now has an Orders button (on the job card and in the Costs window). Raise a skip, portaloo, plant hire, materials or other order with the supplier, dates, site address and price; it gets a PO number (PO-0001, counting up) and can be sent by branded email (logo, company details, please quote the PO on your invoice) or by a ready-written WhatsApp message. Orders on account count as expected costs straight away: the Costs window has a Still to come box and shows Margin so far and Margin including expected costs, turning amber or red against the margin you quoted. Hire is priced by rate and time on site with an overrun warning. When the supplier invoice arrives you add it from the order, or match it to a cost already in the job, and the expected cost stops counting; the app suggests a match but never does it on its own. Materials marked paid when ordered create the paid cost at once. VAT on costs made this way is assumed at 20 percent. Needs supabase/job-orders.sql to be run once on each database. The supplier price form, overdue-invoice reminder and calendar deliveries are still to come.' },
  { at: '2026-10-12T19:41:00+01:00', title: 'Subcontractors: timesheets grouped by week', detail: 'On the Subcontractors page, the Weekly Timesheets list now has a heading for each week (Week of the dates, how many people and days, any pending, and the week total), newest first, with a clear gap between weeks and each subcontractor card for that week underneath in name order. Click a week heading to fold the whole week away.' },
  { at: '2026-10-11T19:55:00+01:00', title: 'Pitched roof covering: flashing choice, soakers and chase at a wall', detail: 'In Roof Coverings (pitched), when the roof meets an existing wall you can now choose the flashing: code 4 lead, code 5 lead, lead-effect or a GRP lead-effect trim. Lead flashing up a sloping edge (a gable or hip end against a wall) gets a lead soaker at every course, a lean-to high wall gets an apron flashing with none. There is a materials line for the chase (lead wedges, mortar and sealant) and a labour line for the roofer cutting the chase, fitting the soakers and pointing in. The customer description names the flashing. All rates and hours are samples.' },
  { at: '2026-10-11T19:42:00+01:00', title: 'Product links: same in every calculator, decoration links shared by room', detail: 'Checked every calculator: all use the same product pop-up. In the decoration calculator a product link is now to the kind of material (for example wall paint), so one link covers every room and every quote instead of one room only. Litres and kilos are understood as units and a tin or tub size (5L, 5kg) is read from the product name, with whole-pack pricing. The computed lump-sum decoration lines (dust sheets and prep sundries) cannot be linked.' },
  { at: '2026-10-11T19:38:00+01:00', title: 'Calculators: search pop-up to link a product, and roll or pack sizes', detail: 'The Link to a product button on a calculator cost line now opens a pop-up with a search box (name, category or supplier) and shows what that line would cost from each product, marking the cheapest of the similar ones. A product sold in another unit, such as a roll of breather membrane, can be linked by saying how much of the line unit one covers (read from names like 1m x 50m roll where it can), and the line then pays for whole packs: 20 m from a 50 m roll costs the whole roll, while a 20 m roll costs just that. A linked line shows what it buys. Pack sizes need supabase/calculator-rate-links-pack.sql to be run once on each database; without it only same-unit products link, as before.' },
  { at: '2026-10-11T19:29:00+01:00', title: 'A margin of its own for one sub-phase', detail: 'In a quote, the Margin figure in a sub-phase header is now a box you can type in, so one sub-phase can have its own margin instead of the quote overall markup. A sub-phase with its own margin shows its box in green with a reset arrow that goes back to the quote margin; the quote-wide Markup slider does not change it. Sub-phases priced by a calculator still set their margin in the calculator. The margin flows through to the client quote, PDF, portal and the breakdown cards, and clients never see the percentage.' },
  { at: '2026-10-11T19:12:00+01:00', title: 'Client portal: unsent quotes and draft invoices are hidden', detail: 'A client now only sees a quote once it has been sent (and afterwards once they have approved or rejected it), and never a draft invoice. Before this, every quote and invoice for that client showed in their portal whatever its status, so a quote you were still working on could appear, and could even be approved while it was only saved. A client can now only approve a quote that has been sent, comments and attachments on an unsent quote are closed to them, and your preview of the portal follows the same rule. The database part is supabase/portal-hide-unsent.sql, which has to be run once on each database (an undo file is next to it).' },
  { at: '2026-10-11T18:00:00+01:00', title: 'Decoration calculator: drying time and days on site', detail: 'The Internal decoration calculator now adds a drying time and return visits allowance, 10% of the painter hours by default (a slider from 0 to 30%), as its own labour line so it can be seen and changed. It also shows an estimate of the days on site: the longer of the painter time in 8 hour days and the longest chain of drying steps in any one room (filler, mist coat or sealer, then each coat, and primer, undercoat and topcoats on woodwork), with the reason for each room on hover. The days figure is for planning and does not yet feed the Gantt.' },
  { at: '2026-10-11T17:40:00+01:00', title: 'Take-off: Decoration now opens the Internal decoration calculator', detail: 'In Take-off, a Decoration area with the Internal Wall and Ceiling Painting sub-phase picked now shows the calculator card and an Open calculator button, like the roof. The drawn area is only a marker on the plan; the rooms are added in the calculator, and its price and description go to the quote when you send the take-off. A Sub-Phase picked before drawing carries onto the area. Decoration items drawn earlier with a flat task keep working as they did until their sub-phase is changed.' },
  { at: '2026-10-11T17:33:00+01:00', title: 'Quotes open with their phases collapsed', detail: 'When you open a quote, saved or new, every phase now starts collapsed, and the sub-phases inside start collapsed too, instead of everything being open. This also applies when the AI, a template or a Take-off import fills a quote in. A single sub-phase you add yourself stays open. Expand All and Collapse All work as before.' },
  { at: '2026-10-11T17:29:00+01:00', title: 'Add Sub-Phase opens on the phase you are in', detail: 'Adding a sub-phase from inside a phase on a quote (for example Decoration) now lists the sub-phases of that phase first, with a tick on any already in the quote, and a link to show the sub-phases of every other phase. Searching still looks through all phases.' },
  { at: '2026-10-11T17:19:00+01:00', title: 'Scope box starts small', detail: 'The scope of works box on New Quote and Quick Quote now starts about four lines tall and scrolls, instead of growing to show all its text. Drag its bottom or right edge to see more. The full-screen AI scope writer still grows with its text.' },
  { at: '2026-10-11T17:04:00+01:00', title: 'New calculator: Internal decoration, room by room', detail: 'The Internal Wall and Ceiling Painting sub-phase under Decoration now has a calculator. Add each room, give its size, doors and windows, then say what state its walls and ceiling are in (new plaster, painted and in good order, painted but flaking or patchy, or wallpapered that has to be stripped) and how much filling and sanding they need. It prices the preparation, a mist coat on new plaster, sealer, stripping with steamer hire, the paint from the area and number of coats, and the painter time, plus the skirting boards, architraves, picture rails, doors and window frames if they are painted too. Cost and paint are shown room by room, with a Copy button for matching rooms. All rates and hours are sample figures to check against real jobs. The old simple tasks under that sub-phase are now replaced by the calculator.' },
  { at: '2026-10-11T16:20:00+01:00', title: 'Scope of works box can be resized', detail: 'The scope of works box has a grip on its bottom edge and right edge: drag the bottom one to make the box taller or shorter, the right one to make it narrower or wider, or the corner for both. It works with a mouse or a finger. The size is not remembered between visits.' },
  { at: '2026-10-11T16:12:00+01:00', title: 'Scope of works: bold, underline and bullets, no more stars', detail: 'The scope of works box (New Quote, Quick Quote and the AI scope workspace) is now a small word-processor with Bold, Underline and Bullet list buttons, also Ctrl+B and Ctrl+U. It shows real bold, underline and bullets instead of asterisks, and the online quote, printed and emailed quotes and the client portal show the same formatting, so the stars the AI used to leave around headings no longer appear. The contract and the invoice description get the words without formatting. In the PDF first-page summary only a bold phrase at the start of a line counts as a heading. Pasting keeps bold, underline and bullets but drops fonts and colours from other places.' },
  { at: '2026-10-11T15:34:00+01:00', title: 'AI review: suggestions on a normal sub-phase now leave a note', detail: 'On a sub-phase that is not priced by a calculator, a suggestion added from the AI review still goes in as a line at 0 pounds in its cost list, but it now also leaves a note on the sub-phase saying what was added, with a Price it button that opens that cost list. The review pop-up explains this before you add anything, and the sub-phase no longer closes itself after a review if notes are waiting.' },
  { at: '2026-10-11T12:55:00+01:00', title: 'Quote breakdown: cards, margin by phase, comparison with past jobs', detail: 'The breakdown at the bottom of a quote is now a set of cards: Your cost, Your margin (in pounds, as a percentage on cost and of the sell price), Sell price and your target margin (the quote margin setting); a card for each cost type (labour, materials, plant, subcontract, other) with its share of cost and its margin; and Margin by phase, green, amber or red against your target, where you can tap a phase to see its sub-phases. Below that, Compared with your similar jobs checks each sub-phase against the same sub-phase on your own won quotes and says where this one is much cheaper or dearer and which cost type accounts for it, and Things to look at lists plain flags (a sub-phase well under your target margin, sub-phases with nothing priced, no plant or contingency priced). Won quotes are now remembered with the real cost and the own margin of each sub-phase, and rejected quotes are remembered as lost, so the comparison gets better as you win jobs. Everything is ex VAT and the labour-by-trade tables are still underneath.' },
  { at: '2026-10-11T12:35:00+01:00', title: 'AI review suggestions on calculator sub-phases become notes', detail: 'On a calculator sub-phase, a suggestion from the AI review is now kept as a note ("+ Add as note") shown on the sub-phase and at the top of the calculator when you recalculate, with a tick and a remove button, instead of a hidden cost row that Recalculate wiped. Sub-phases without a calculator still get a visible cost row. No SQL needed.' },
  { at: '2026-10-11T12:26:00+01:00', title: 'AI review: fixed the "not valid JSON" error', detail: 'The AI phase review could end with a "not valid JSON" message when it ran past the host\'s time limit. It now uses the faster AI model with its own time limit, and shows a plain "took too long, try again" message if the host ever sends an error page instead. No SQL needed.' },
  { at: '2026-10-11T12:19:00+01:00', title: 'Description: say it, the AI writes it; review checks your price', detail: 'The Description box on a quote sub-phase has a "Say it" mic and a "Write it" button: dictate or type a few rough words about the work and the AI writes the short scope-of-works line printed under the sub-phase name (never any price, cost or profit wording), with Undo. The AI review (robot button) now reads that description, what is priced for it and the margin, and starts with a price check (looks low, about right or high, with reasons) and flags anything the description mentions that is not priced. Each use counts towards your AI allowance. No SQL needed.' },
  { at: '2026-10-11T11:53:00+01:00', title: 'Quote phases: tidier layout', detail: 'On a quote, each sub-phase now has one total: its Cost, Margin and Sell (all ex VAT) sit in the sub-phase header row when it is open, and the separate costing box is gone. A room shows its own subtotal only when it has more than one sub-phase, and the phase total says ex VAT. The header row wraps on a narrow tablet or phone. Layout only; no prices change. No SQL needed.' },
  { at: '2026-10-11T11:46:00+01:00', title: 'Margin: one per sub-phase, shown ex VAT', detail: 'A calculator\'s profit % is now that sub-phase\'s own margin (% added on top of cost) instead of a Profit cost line, and it replaces the quote\'s overall markup for that sub-phase, so the two no longer stack. Each sub-phase shows Cost (ex VAT), Margin n% on cost and Sell (ex VAT). Quotes saved before this keep their prices until a calculator sub-phase is saved again; clients still never see the margin. No SQL needed.' },
  { at: '2026-10-11T11:24:00+01:00', title: 'Clients never see profit on calculator items', detail: 'A calculator sub-phase\'s own "Profit" row and its cost-rate notes (such as "110 nr @ £0.80/nr (10% waste)") no longer appear anywhere a client sees the quote: the client view, detailed view, online quote, printed quote and PDF. The profit is spread across the other rows so phase and quote totals do not change, and your own quote screens still show it. The PDF\'s per-item prices now use each item\'s full price. No SQL needed.' },
  { at: '2026-10-11T11:18:00+01:00', title: 'Saved quotes keep their prices; Refresh button removed', detail: 'The "Refresh from Back Office" button is removed from the quote toolbar: a new calculator starts from the current Back Office prices and a saved quote is a record that only changes when you change it. A calculator opened from a saved quote now keeps the prices it was saved with (before, a line linked to a Back Office product could quietly take today\'s price); a linked line offers a "↻ now" button to update it on request. No SQL needed.' },
  { at: '2026-10-11T11:05:00+01:00', title: 'Quote sub-phase: clearer labels', detail: 'The "Task Name" box on a quote sub-phase is now labelled "Description" (shown under the sub-phase name on the quote), and the sub-phase name says on hover that renaming it is for this quote only and does not change Back Office. Labels only. No SQL needed.' },
  { at: '2026-10-11T11:01:00+01:00', title: 'Quote phases: tidier buttons', detail: 'The extra "+ Sub-phase" buttons inside a phase (in each room row, and under a list with no room) are removed, as is the "+ Task" button that did nothing. The "+ Sub-phase" in the phase header is the one way to add; when the phase already has rooms, its picker now has a "Put it in" dropdown to choose the room. No SQL needed.' },
  { at: '2026-10-11T10:49:00+01:00', title: 'Quote: "↑ BO" button removed', detail: 'The "↑ BO" button on a quote sub-phase (which wrote that sub-phase\'s prices over the Back Office default rates) has been removed, so a one-off price in a quote can no longer change the standard rates by accident. Default rates are edited in Back Office. No SQL needed.' },
  { at: '2026-10-11T10:46:00+01:00', title: 'Quote sub-phase: one way into the calculator', detail: 'The extra Calculator button in a sub-phase header is gone: the Open Calculator / Recalculate button in the sub-phase card is the way in, and Recalculate opens the calculator as you left it. A Task Name you have typed over is no longer overwritten when the calculator is saved again. No SQL needed.' },
  { at: '2026-10-11T10:35:00+01:00', title: 'Saved calculators open again as you left them', detail: 'An assembly calculator now keeps what was typed into it when you press Save & Price, with the quote sub-phase or the Take-off item, so opening it again shows it as you left it and you can edit and save again (before, it opened blank). The Task Name on a sub-phase is now a two-line description box that can be cleared and rewritten without the original wording coming back while you type. Calculators saved before this open fresh once. No SQL needed.' },
  { at: '2026-10-11T10:21:00+01:00', title: 'Tablet and installed app: files open with a Close button', detail: 'On a tablet, a phone or the installed app, PDFs, pictures, attachments, printable pages (materials lists, quote previews, invoices, job reports) and links to files or the app\'s own pages now open full screen inside the app with a Close button (Esc and the device Back also close it), instead of a new tab with no way back. Printable pages have a Print button. Desktop browsers are unchanged. No SQL needed.' },
  { at: '2026-10-11T10:11:00+01:00', title: 'AI quote prices the electrical installation', detail: 'When the scope describes electrical work, the AI quote now prices the electrical installation room by room with the calculator: the rooms named, the points stated (a room named with no points gets its usual set, listed in the review note), special fittings such as a chandelier, and whole-house items such as a new consumer unit. It never adds a room or count the scope does not mention. The calculator opens showing the same rooms, and the scope chat now asks about electrics and writes them room by room. No SQL needed.' },
  { at: '2026-10-11T10:00:00+01:00', title: 'Take-off: electrical points on the plan', detail: 'In the Electrics phase a new tool places electrical points on the plan: pick a kind of point (sockets, switches, lights, extractors, alarms, data), click where it goes, and it is counted in its room (taken from a named floor area it sits in, or typed). Points can be moved, changed, deleted or marked as a special fitting. They feed the electrical installation calculator, whose room counts follow the plan until typed over; the calculator now keeps what you set with the Take-off project, and warns when the plan has changed since it was priced. No SQL needed.' },
  { at: '2026-10-10T20:15:00+01:00', title: 'New calculator: Electrical installation', detail: 'Prices the whole electrical installation room by room, per point at an electrician\'s all-in rate: add a kitchen, bathroom, bedroom and so on, each with its usual points to adjust. A situation percentage (refurbishment, occupied house, hard to reach, listed building) can be set for the job or a room; special fittings such as a chandelier are an extra install charge, client-supplied or ours; a room can be priced by the day; whole-house items cover the consumer unit, testing and certificate and extra circuits. A new sub-phase under Electrics (restore the Electrics phase first if it was deleted, then open Back Office once). Not yet in Take-off. No SQL needed.' },
  { at: '2026-10-10T19:58:00+01:00', title: 'AI writer: faster voice and resizable', detail: 'The read-aloud voice has a speed picker (default 1.15 times, up to 2 times). The AI writer pop-up can be dragged wider or taller by its left and top edges, or expanded with a button, and the AI writer column on the full AI quote screen can be dragged wider. Sizes are remembered on each device. No SQL needed.' },
  { at: '2026-10-10T19:49:00+01:00', title: 'AI scope chat can read aloud', detail: 'A speaker button on each reply from the AI scope chat (the interview questions and the finished scope) reads it out with the voice built into your device, with a Stop button and, where the device has several voices, a voice picker. It stops when you send a message or start dictating. Free, and nothing is sent anywhere. No SQL needed.' },
  { at: '2026-10-10T19:41:00+01:00', title: 'Cavity wall: labour starts sized from the wall', detail: 'The cavity wall calculator now opens with one bricklayer labour line (1 hour per m2 of wall, following the wall size until you edit it), instead of a typed 12 hours with no trade picked. This is the same labour the AI quote uses, so the AI price and the calculator now agree. No SQL needed.' },
  { at: '2026-10-10T19:38:00+01:00', title: 'AI quote prices the foundation calculators', detail: 'When the scope states the sizes, the AI quote now prices strip foundation, trench fill, raft, pads, piled foundation and underpinning with each calculator\'s standard settings (cavity walls already worked this way), and flags them for review. Opening the calculator from the quote shows the same sizes. The scope chat now asks about foundation type and sizes and writes them as numbers. With no sizes stated the line stays "Not yet calculated". No SQL needed.' },
  { at: '2026-10-10T19:05:00+01:00', title: 'Calculators: link rates to Back Office prices', detail: 'In any calculator, a materials line can be linked to a Product and a plant line to a Plant item (same unit only). A linked line uses that item\'s price and follows it when it changes; unlink puts the sample rate back. Labour already uses your trades. Needs supabase/calculator-rate-links.sql to save links.' },
  { at: '2026-10-10T18:54:00+01:00', title: 'New calculator: Underpinning', detail: 'Prices traditional mass concrete underpinning in pins from the drawn line of wall: hand digging, skips, concrete, dry pack and shuttering, with optional props and reinforcement, labour, a quote description and a section drawing. A new sub-phase under Foundations; in Take-off, set Foundation Type to Underpinning.' },
  { at: '2026-10-10T18:43:00+01:00', title: 'New calculator: Piled Foundation', detail: 'Prices piles (a subcontract price per metre plus a rig charge, count from the spacing or typed) with a shuttered, caged ground beam on top, from the drawn line, with labour, a quote description and a section drawing. A new sub-phase under Foundations; in Take-off, set Foundation Type to Piled Foundation. This completes the five foundation calculators: strip, trench fill, raft, pad and piled.' },
  { at: '2026-10-10T18:28:00+01:00', title: 'New calculator: Pad Foundations', detail: 'Prices pad foundations from the number of pads and their size (more groups for different sizes): pits, blinding, concrete, soil away, with optional formwork, reinforcement and column starters, plus labour, a quote description and a section drawing. A new sub-phase under Foundations; in Take-off, a rectangle in Foundations set to Pad Foundations opens it.' },
  { at: '2026-10-10T18:19:00+01:00', title: 'Take-off: raft foundations drawn as a shape', detail: 'A rectangle or polygon in Foundations set to Raft Foundation (or the Raft sub-phase picked first) opens the Raft calculator, sized from its box. A foundation line no longer gets the raft calculator by mistake (it only gets strip or trench fill).' },
  { at: '2026-10-10T18:13:00+01:00', title: 'New calculator: Raft Foundation', detail: 'Prices a raft from its footprint: bulk dig and soil away, hardcore, blinding, DPM, optional insulation and edge beam, edge formwork, mesh and concrete (optionally pumped), with labour, a quote description and a section drawing. A new sub-phase under Foundations. Not yet opened from Take-off.' },
  { at: '2026-10-10T18:07:00+01:00', title: 'New calculator: Trench Fill Foundation', detail: 'Prices a trench filled with concrete to a set distance below ground, with the wall up to DPC, from the drawn line. A new sub-phase under Foundations, and the default Foundation Type in Take-off now opens this calculator. The labour panel wording now says foundation / parapet wall instead of roof.' },
  { at: '2026-10-10T17:58:00+01:00', title: 'Take-off: strip foundations priced by their calculator', detail: 'A drawn foundation line set to Strip Footing is priced by the Strip Foundation calculator (summary card and full-size window), and a sub-phase picked before drawing carries onto the line. Open Back Office once so the new sub-phase appears in your list.' },
  { at: '2026-10-10T17:46:00+01:00', title: 'New calculator: Strip Foundation (Traditional)', detail: 'Prices a strip foundation from its length: the trench and machine, soil taken away, concrete, blockwork up to DPC (solid or cavity filled), DPC, backfill and labour, with a quote description and section drawing. A new sub-phase under Foundations. Not yet opened from Take-off.' },
  { at: '2026-10-10T17:31:00+01:00', title: 'Owner area: one Change log', detail: 'Software updates and every change to Phases & Tasks now appear together in one list, with filters and search.' },
  { at: '2026-10-10T17:22:00+01:00', title: 'Phase change history', detail: 'The database now records every change to Phases & Tasks: what changed, before and after, who and when. Read it in the Owner area. Needs supabase/bo-change-log.sql.' },
  { at: '2026-10-10T16:46:00+01:00', title: 'AI wording on every sub-phase', detail: 'A "What this covers (for the AI)" box on each sub-phase, with suggested wording for all the built-in ones. The AI quote reads it to choose the right sub-phase. Needs supabase/sub-phase-ai-hint.sql to save your own wording.' },
  { at: '2026-10-10T16:41:00+01:00', title: 'AI quote prefers the calculators and groups phases correctly', detail: 'Each calculator sub-phase is described to the AI, which is told to prefer it over a general phase for the same work. A phase is grouped under the main phase Phases & Tasks puts it in, not the one the AI guessed.' },
  { at: '2026-10-10T16:25:00+01:00', title: 'AI scope of works only covers the work described', detail: 'For a single element such as one wall, the scope no longer lists demolition, foundations, structure and every other default phase.' },
  { at: '2026-10-10T16:17:00+01:00', title: 'AI quote prices a cavity wall from its length and height', detail: 'The AI hands the size it heard to the cavity wall calculator, which prices the wall with its standard settings. Calculator sub-phases start at "Not yet calculated" instead of carrying leftover flat lines.' },
  { at: '2026-10-10T15:50:00+01:00', title: 'Deleted wall build-ups stay deleted', detail: 'Deleted External Walls, Floors, Foundations and Plastering build-ups and their layers are no longer put back, and edited layer names and prices are kept.' },
  { at: '2026-10-10T15:24:00+01:00', title: 'Your edits in Phases & Tasks stick', detail: 'Back Office no longer overwrites the names, order or units you set, and a deleted standard phase, sub-phase or task stays deleted, with a Restore list at the bottom. Needs supabase/bo-deleted-items.sql.' },
  { at: '2026-10-10T14:09:00+01:00', title: 'Standard job types are templates too', detail: 'Rear Extension, Loft Conversion and the rest appear in My templates, empty to start with and quoted the old way until you fill them in.' },
  { at: '2026-10-10T13:54:00+01:00', title: 'My templates', detail: 'Named templates built from the sub-phases in Phases & Tasks, offered when starting a manual quote. Prices, tasks and calculators stay in Phases & Tasks. Needs supabase/quote-templates.sql.' },
  { at: '2026-10-10T11:51:00+01:00', title: 'Subcontractor timesheets: full day, half day or split day', detail: 'A subcontractor can record a half day, or two jobs in one day (each a half day), so a short day is no longer paid as a full day.' },
  { at: '2026-10-10T11:15:00+01:00', title: 'Contacts: row Delete button removed', detail: 'Deleting is done from Tidy up contacts.' },
  { at: '2026-10-10T11:07:00+01:00', title: 'Contacts: deleted contacts stay deleted', detail: 'Xero sync no longer brings back a contact you deleted, optional archive in Xero, and a Tidy up contacts screen to remove many at once with a restore list. Needs supabase/deleted-contacts.sql.' },
  { at: '2026-10-09T20:00:00+01:00', title: 'Dashboard: drag to move and resize cards', detail: 'On a computer, drag a card to move it and drag its right-hand edge to resize it. Cards in a row are the same height.' },
  { at: '2026-10-09T17:57:00+01:00', title: 'Dashboard as a grid of cards', detail: 'Greeting, needs-attention, headline cards, this week on site, active jobs and job margins as cards you can arrange; layout remembered per login.' },
  { at: '2026-10-09T14:29:00+01:00', title: 'Documents: save as subcontractor fixed quote', detail: 'Creates the fixed quote with the emailed document attached, with no bill or job cost, then straight to adding payment stages.' },
  { at: '2026-10-08T16:14:00+01:00', title: 'Subcontractor portal: Talk buttons', detail: 'Dictate "Describe your day" and "What did you work on?" instead of typing.' },
  { at: '2026-10-08T15:59:00+01:00', title: 'Subcontractor notes: Talk button', detail: 'Dictate a note with the phone\'s speech recognition.' },
  { at: '2026-10-08T15:06:00+01:00', title: 'Contact panels by type', detail: 'Clients, subcontractors and suppliers each get the panel that suits them (quotes and jobs, timesheets and pay, spend and bills).' },
  { at: '2026-10-08T14:58:00+01:00', title: 'Contact panel: tidier header', detail: 'Name and window buttons on one line; no + Quote button for subcontractors.' },
  { at: '2026-10-08T14:51:00+01:00', title: 'Subcontractor portal: Fixed-price payments', detail: 'Payments is now "Fixed-price payments" and points day-rate and hourly subcontractors to Timesheets.' },
  { at: '2026-10-08T14:41:00+01:00', title: 'Deleting a portal-sourced weekly day removes the original', detail: 'It no longer reappears in the subcontractor\'s portal.' },
  { at: '2026-10-08T14:38:00+01:00', title: 'Subcontractor portal loads faster', detail: 'Main data, schedule and company calendar load together instead of one after another.' },
  { at: '2026-10-08T14:33:00+01:00', title: 'Subcontractor portal has its own app settings', detail: 'The home-screen icon opens the portal, and the builder\'s screens are no longer flashed to a subcontractor or client.' },
  { at: '2026-10-08T14:18:00+01:00', title: 'Approved portal timesheets go into the weekly timesheet', detail: 'Paid with the week like any logged day; the subcontractor sees approved, then paid.' },
  { at: '2026-10-08T14:01:00+01:00', title: 'Job note photos are more reliable', detail: 'Phone photos in odd formats are converted, clear reasons when a photo can\'t go, and a "Try the photo again" button.' },
  { at: '2026-10-08T13:52:00+01:00', title: 'New subcontractor notes are flagged', detail: 'A red "new" badge on a job\'s Notes button, NEW tags in the Activity Log, and a "Needs your attention" dashboard card.' },
  { at: '2026-10-08T13:19:00+01:00', title: 'Job pickers list jobs that are on site', detail: 'Subcontractor timesheet, notes and preview pickers use jobs that are active and not archived. Needs the updated SQL.' },
  { at: '2026-10-08T13:15:00+01:00', title: 'Job notes: accept the jobs the portal offers', detail: 'Clearer error messages on the notes page.' },
  { at: '2026-10-07T20:26:00+01:00', title: 'Subcontractor Company Calendar: week strip', detail: 'Seven day buttons with dots and a card for the chosen day replace the month grid.' },
  { at: '2026-10-07T20:21:00+01:00', title: 'Subcontractor portal: Add my time and Timesheets split', detail: 'Add my time opens just the form; recorded timesheets have their own page.' },
  { at: '2026-10-07T20:15:00+01:00', title: 'Subcontractor portal home: tiles', detail: 'Tiles open their own page with a Home button; the builder\'s preview matches.' },
  { at: '2026-10-07T20:10:00+01:00', title: 'Subcontractor portal redesign', detail: 'A big readable home screen with stat cards and app-style tiles, and a "Your look" sheet with four tile styles and Normal or Large text.' },
  { at: '2026-10-07T20:00:00+01:00', title: 'Subcontractor job notes with photos', detail: 'Notes and photos against a job, landing in the job\'s Activity Log labelled with their name.' },
  { at: '2026-10-07T19:53:00+01:00', title: 'Calendar tab renamed Company Calendar', detail: 'Shown as plain Calendar only when the company view is switched off for that person.' },
  { at: '2026-10-07T19:45:00+01:00', title: 'Task days: clicking a day picks just that day', detail: 'Fixes Friday appearing to move to Monday; "Every day" is its own button.' },
  { at: '2026-10-07T19:32:00+01:00', title: 'Big Add my time button on the subcontractor dashboard', detail: 'The builder\'s preview shows it too.' },
  { at: '2026-10-07T19:22:00+01:00', title: 'Simpler subcontractor timesheet form', detail: 'Job, date, start, finish and lunch with hours worked out automatically; the describe-your-day AI is an optional shortcut.' },
  { at: '2026-10-07T19:17:00+01:00', title: 'Subcontractor calendar readable on busy days and phones', detail: 'Company work shown as one quiet count per day, with a dot grid on phones.' },
  { at: '2026-10-07T19:06:00+01:00', title: 'Fix: subcontractors locked out of their portal', detail: 'Database function repair so subcontractors can sign in again.' },
  { at: '2026-10-07T19:01:00+01:00', title: 'Subcontractor portal error screens', detail: 'They show which email you are signed in as, with a Sign out button.' },
  { at: '2026-10-07T18:49:00+01:00', title: 'Repair: subcontractors with a client-type login', detail: 'Fixes "Account not linked" and heals it on sign-in.' },
  { at: '2026-10-07T16:16:00+01:00', title: 'Subcontractor Calendar tab', detail: 'Their booked days in green plus the company\'s other jobs in grey, with a per-subcontractor switch.' },
  { at: '2026-10-07T15:57:00+01:00', title: 'Calendar month view shows every task', detail: 'Each week grows to fit instead of hiding extras behind "+N more".' },
  { at: '2026-10-07T14:47:00+01:00', title: 'Subcontractor invites go to the subcontractor portal', detail: 'Invite, app, SMS and WhatsApp links no longer use the client portal ones.' },
]
